class C {
  *items() { yield 1; yield 2; }
  [Symbol.iterator]() { return this.items(); }
  wrap() { return this.items(); }
}
class D { *[Symbol.iterator]() { yield "x"; yield "y"; } }
function main(): void {
  console.log([...new C()], Array.from(new C()), [...new C().wrap()]);
  console.log([...new D()]);
  for (const v of new C()) console.log(v + 1);
}
